Think: For each filename in the manifest, read the corresponding file from temp_workspace/employees/, extract non-empty lines preserving order, and write them to temp_workspace/cleaned/{employee_id}.txt. I'll use a single awk command to process the manifest and create/truncate each cleaned file correctly.

Act: bash

```bash
awk '{
  fname=$0;
  id=fname; sub(/\.txt$/,"",id);
  infile="temp_workspace/employees/" fname;
  outfile="temp_workspace/cleaned/" id ".txt";
  first[id]=0;
  while((getline line < infile) > 0){
    if(line !~ /^[[:space:]]*$/){
      if(first[id]==0){ print line > outfile; first[id]=1 } else { print line >> outfile }
    }
  }
  close(infile);
  close(outfile);
}' temp_workspace/file_list.txt
```

