Think: Convert the normalized value in temp_check/var_normalized.txt into an integer-like canonical form and record result/errors to temp_check/var_conversion.txt.

Act: bash

```bash
awk '{
s = $0
}
END {
if (s == "" ) {
  print "error: empty value"
} else if (s ~ /^[+-]?[0-9]+$/) {
  num = s
  if (num ~ /^\+/) num = substr(num,2)
  sign = ""
  if (num ~ /^-/) { sign = "-" ; num = substr(num,2) }
  sub(/^0+/, "", num)
  if (num == "") num = "0"
  print "result: " (sign == "-" ? "-" : "") num
} else {
  print "error: not integer"
}
}' temp_check/var_normalized.txt > temp_check/var_conversion.txt
```

